CREATE TABLE `ea_tbot_client` (
  `nid` int(11) NOT NULL,
  `nuser_id` int(11) NOT NULL COMMENT 'Liên kết sang tài khoản người dùng ea_tuser(nid)',
  `cmt5_account` varchar(50) NOT NULL COMMENT 'Số tài khoản MT5 của Client',
  `cmt5_password` varchar(255) NOT NULL COMMENT 'Mật khẩu tài khoản sàn MT5 (Mã hóa)',
  `cbroker_name` varchar(100) DEFAULT NULL COMMENT 'Tên sàn giao dịch của tài khoản khách hàng',
  `cbot_version` varchar(50) NOT NULL DEFAULT 'RSI6_v33' COMMENT 'Phiên bản Bot (RSI6_v32, RSI6_v33)',
  `callow_grid_near_end` char(1) DEFAULT '0' COMMENT '1: Cho phép nhồi lệnh khi >8 lệnh sát phiên (v33), 0: Ngắt nhồi',
  `clicense_key` varchar(100) NOT NULL COMMENT 'Mã bản quyền EA từ xa',
  `dlicense_expiry` date NOT NULL COMMENT 'Ngày hết hạn sử dụng Bot',
  `fbalance` decimal(15,2) DEFAULT 0.00 COMMENT 'Số dư tài khoản cập nhật từ EA',
  `fequity` decimal(15,2) DEFAULT 0.00 COMMENT 'Tài sản thực tế sau khi trừ lệnh âm',
  `fdrawdown` decimal(5,2) DEFAULT 0.00 COMMENT 'Tỷ lệ sụt giảm tài khoản tạm thời (%)',
  `fprofit` decimal(15,2) DEFAULT 0.00,
  `cbot_status` char(1) DEFAULT '0' COMMENT '1: Khởi chạy (Running), 0: Tạm ngừng (Stop)',
  `cdel` char(1) DEFAULT '0' COMMENT '1: Đã xóa, 0: Hoạt động',
  `ddate_created` datetime DEFAULT current_timestamp(),
  `ddate_updated` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `nuser_created` int(11) DEFAULT NULL,
  `nuser_updated` int(11) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=COMPACT;

