  `npair_close_tu_lenh` int(11) DEFAULT 9 COMMENT 'Bắt đầu áp dụng từ lệnh thứ N',
  `fpair_close_so_usd` double DEFAULT 2 COMMENT 'Mức lợi nhuận USD để chốt cặp',
  `cpair_close_chot_dan_ve` char(1) DEFAULT '0' COMMENT '1: chốt liên tiếp nhiều cặp (chốt dần về), 0: Tắt',
  `fbasket_tp_phan_tram` double DEFAULT 0 COMMENT 'Tỷ lệ % trailing chốt lời chuỗi',
  `cstep_distances` text DEFAULT NULL COMMENT 'Cấu hình mảng JSON cho các bước G1 đến G25'
